INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2018-spring-am-14','exam-sg','セキュア開発・セキュリティバイデザイン','standard','single_choice','【平成30年度 春期 午前 問14】セキュリティバイデザインの説明はどれか。','[{"id":"a","text":"開発済みのシステムに対して，第三者の情報セキュリティ専門家が脆弱性診断を行い，システムの品質及びセキュリティを高めることである"},{"id":"b","text":"開発済みのシステムに対して，リスクアセスメントを行い，結果に基づいてシステムを改修することである"},{"id":"c","text":"システムの運用において，第三者による監査結果を基にシステムを改修することである"},{"id":"d","text":"システムの企画・設計段階からセキュリティを確保する方策のことである"}]','"d"','セキュリティバイデザインは企画・設計の初期段階からセキュリティを組み込む考え方。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-15','exam-sg','認証情報管理・パスワードマネージャ','standard','single_choice','【平成30年度 春期 午前 問15】A社では，インターネットを介して提供される複数のクラウドサービスを共用PCから利用している。共用PCの利用者IDは従業員間で共用しているが，クラウドサービスの利用者IDは従業員ごとに異なる。本人以外による不正ログインの防止の観点から，適切なパスワード管理方法はどれか。','[{"id":"a","text":"各従業員が指紋認証で保護されたスマートフォンをもち，スマートフォン上の信頼できるパスワード管理アプリケーションに各自のパスワードを記録する"},{"id":"b","text":"各従業員が複雑で推測が難しいパスワードを一つ定め，どのクラウドサービスでもそのパスワードを設定する"},{"id":"c","text":"パスワードを共用PCのWebブラウザに記憶させ，次回以降に自動入力されるように設定する"},{"id":"d","text":"パスワードを平文のテキストファイル形式で記録し，共用PCのOSのデスクトップに保存する"}]','"a"','個人の生体認証で保護された端末と信頼できるパスワード管理アプリを使い，サービスごとの認証情報を安全に管理する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-16','exam-sg','マルウェア検知・ハッシュ値','standard','single_choice','【平成30年度 春期 午前 問16】ワームの検知方式の一つとして，検査対象ファイルからSHA-256を使ってハッシュ値を求め，既知のワーム検体ファイルのハッシュ値データベースと照合する方式がある。この方式で検知できるものはどれか。','[{"id":"a","text":"ワーム検体と同一のワーム"},{"id":"b","text":"ワーム検体と特徴あるコード例が同じワーム"},{"id":"c","text":"ワーム検体とファイルサイズが同じワーム"},{"id":"d","text":"ワーム検体の亜種に該当するワーム"}]','"a"','ハッシュ値が一致するのは基本的に同一内容のファイルであり，亜種やサイズだけ同じファイルは一致しない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-17','exam-sg','脆弱性管理・IT資産管理','standard','single_choice','【平成30年度 春期 午前 問17】A社では，利用ソフトウェアの脆弱性に対してベンダ提供の最新セキュリティパッチを適用することを決定した。組織内PCやサーバのパッチ適用漏れを防ぐために有効なものはどれか。','[{"id":"a","text":"ソフトウェア製品の脆弱性の概要や対策情報が蓄積された脆弱性対策情報データベース"},{"id":"b","text":"脆弱性の特性や深刻度を評価するための共通脆弱性評価システム（CVSS）"},{"id":"c","text":"ソフトウェア製品のソースコードを保存し，アクセス権と変更履歴を管理するソースコード管理システム"},{"id":"d","text":"ソフトウェア製品の名称やバージョン，導入機器の所在，IPアドレスを管理するIT資産管理システム"}]','"d"','機器とインストール済みソフトウェアのバージョンを把握できるIT資産管理システムが，適用漏れの確認に有効。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-20','exam-sg','DNS・ドメイン名ハイジャック','standard','single_choice','【平成30年度 春期 午前 問20】ドメイン名ハイジャックを可能にする手口はどれか。','[{"id":"a","text":"PCとWebサーバとの通信を途中で乗っ取り，不正にデータを取得する"},{"id":"b","text":"Webサーバに送信元を偽造したリクエストを大量送信して，Webサービスを停止させる"},{"id":"c","text":"Webページにアクセスする際のURLに余分なドットやスラッシュなどを含め，アクセスが禁止されているディレクトリにアクセスする"},{"id":"d","text":"権威DNSサーバに登録された情報を不正に書き換える"}]','"d"','ドメイン名ハイジャックは，権威DNSなどの登録情報を不正に変更し，名前解決先を乗っ取る手口。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-21','exam-sg','Web攻撃・ドライブバイダウンロード','standard','single_choice','【平成30年度 春期 午前 問21】ドライブバイダウンロード攻撃に該当するものはどれか。','[{"id":"a","text":"PC内のマルウェアを遠隔操作して，PCのハードディスクドライブを丸ごと暗号化する"},{"id":"b","text":"外部ネットワークからファイアウォールの設定ミスを突いて侵入し，内部ネットワークのサーバにルートキットを仕掛ける"},{"id":"c","text":"公開Webサイトの入力フィールドにスクリプトを入力し，Webサーバがアクセスするデータベース内のデータを不正にダウンロードする"},{"id":"d","text":"利用者が公開Webサイトを閲覧したとき，利用者の意図にかかわらずPCにマルウェアをダウンロードさせて感染させる"}]','"d"','ドライブバイダウンロードは，Webサイトを閲覧した利用者の意図に反してマルウェアをダウンロード・感染させる攻撃。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-22','exam-sg','生体認証・FRRとFAR','standard','single_choice','【平成30年度 春期 午前 問22】バイオメトリクス認証システムの判定しきい値を変化させるとき，FRR（本人拒否率）とFAR（他人受入率）との関係はどれか。','[{"id":"a","text":"FRRとFARは独立している"},{"id":"b","text":"FRRを小さくすると，FARも小さくなる"},{"id":"c","text":"FRRを小さくすると，FARは大きくなる"},{"id":"d","text":"FRRを大きくすると，FARも大きくなる"}]','"c"','判定しきい値を緩めて本人拒否率（FRR）を下げると，他人受入率（FAR）は上がる傾向がある。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja');
